-- ============================================================================
-- KrishiBondhu Bangladesh: Seed All Geo Tables for Supabase
-- Safe, Idempotent, No Table Alters on Users, No Truncate Cascades, RLS Enabled
-- ============================================================================

-- 1. Ensure schema geo exists
CREATE SCHEMA IF NOT EXISTS geo;

CREATE TABLE IF NOT EXISTS geo.divisions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    bbs_code VARCHAR(10) UNIQUE NOT NULL,
    name_en VARCHAR(100) NOT NULL,
    name_bn VARCHAR(100) NOT NULL,
    is_active BOOLEAN DEFAULT TRUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS geo.districts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    division_id UUID NOT NULL REFERENCES geo.divisions(id) ON DELETE CASCADE,
    bbs_code VARCHAR(10) UNIQUE NOT NULL,
    name_en VARCHAR(100) NOT NULL,
    name_bn VARCHAR(100) NOT NULL,
    is_active BOOLEAN DEFAULT TRUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS geo.upazilas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    district_id UUID NOT NULL REFERENCES geo.districts(id) ON DELETE CASCADE,
    bbs_code VARCHAR(10) UNIQUE NOT NULL,
    name_en VARCHAR(100) NOT NULL,
    name_bn VARCHAR(100) NOT NULL,
    is_active BOOLEAN DEFAULT TRUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS geo.unions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    upazila_id UUID NOT NULL REFERENCES geo.upazilas(id) ON DELETE CASCADE,
    bbs_code VARCHAR(10) NOT NULL,
    name_en VARCHAR(100) NOT NULL,
    name_bn VARCHAR(100) NOT NULL,
    is_active BOOLEAN DEFAULT TRUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL
);

-- 2. Security: Enable RLS and grant read-only access to public
ALTER TABLE geo.divisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE geo.districts ENABLE ROW LEVEL SECURITY;
ALTER TABLE geo.upazilas ENABLE ROW LEVEL SECURITY;
ALTER TABLE geo.unions ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'geo' AND tablename = 'divisions' AND policyname = 'public_read_divisions') THEN
        CREATE POLICY public_read_divisions ON geo.divisions FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'geo' AND tablename = 'districts' AND policyname = 'public_read_districts') THEN
        CREATE POLICY public_read_districts ON geo.districts FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'geo' AND tablename = 'upazilas' AND policyname = 'public_read_upazilas') THEN
        CREATE POLICY public_read_upazilas ON geo.upazilas FOR SELECT USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'geo' AND tablename = 'unions' AND policyname = 'public_read_unions') THEN
        CREATE POLICY public_read_unions ON geo.unions FOR SELECT USING (true);
    END IF;
END $$;

